from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse in serialized rows."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional input frame and lightweight shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute exact common-prefix length with binary-searched C-level slice comparisons."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return ideal character-Trie reuse as sorted adjacent serialized-row LCP totals."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize every source row using its supplied row-specific column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    @classmethod
    def _leaf_score(cls, cells, rows, order) -> int:
        """Score one conditional leaf using the exact sorted-string Trie objective."""
        strings = [
            "".join(cells[row, column] for column in order)
            for row in rows
        ]
        return cls._trie_score(strings)

    @staticmethod
    def _column_stats(values):
        """Return length-weighted repetition and unweighted ordered-pair repetition."""
        counts = {}
        for value in values:
            counts[value] = counts.get(value, 0) + 1

        weighted = 0
        pairs = 0
        for value, count in counts.items():
            pairs += count * (count - 1)
            weighted += len(value) * count * (count - 1)

        return weighted, pairs

    def _global_order(self, cells, mode: int) -> List[int]:
        """Rank all columns globally by one of two bounded repetition heuristics."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            values = cells[:, column]
            weighted, pairs = self._column_stats(values)
            total_length = sum(len(value) for value in values)

            if mode == 0:
                key = weighted
            else:
                key = pairs * max(1, total_length // max(1, n))

            ranked.append((key, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _refine_leaf(self, cells, rows, order) -> List[int]:
        """Apply two bounded exact adjacent-swap passes to the leaf suffix."""
        current = list(order)

        if len(current) < 2 or len(rows) < 2:
            return current

        current_score = self._leaf_score(cells, rows, current)
        boundary_count = min(12, len(current) - 1)

        # The two fixed directions allow improvements to propagate locally
        # without introducing an unbounded permutation search.
        for reverse in (False, True):
            positions = (
                range(boundary_count - 1, -1, -1)
                if reverse
                else range(boundary_count)
            )

            for position in positions:
                trial = current[:]
                trial[position], trial[position + 1] = (
                    trial[position + 1],
                    trial[position],
                )

                trial_score = self._leaf_score(cells, rows, trial)
                if trial_score > current_score:
                    current = trial
                    current_score = trial_score

        return current

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Choose a repeated leading field and exact-refine each group's suffix."""
        n, m = cells.shape
        identity = list(range(m))

        if m <= 1 or n <= 1:
            return [identity[:] for _ in range(n)]

        lead_candidates = []
        for column in range(m):
            weighted, _ = self._column_stats(cells[:, column])
            lead_candidates.append((weighted, column))

        lead = max(
            lead_candidates,
            key=lambda item: (item[0], -item[1]),
        )[1]

        groups = {}
        for row in range(n):
            groups.setdefault(cells[row, lead], []).append(row)

        remaining = [column for column in range(m) if column != lead]
        result = [None] * n

        for rows in groups.values():
            ranked = []

            for column in remaining:
                weighted, _ = self._column_stats(cells[rows, column])
                ranked.append((weighted, column))

            ranked.sort(key=lambda item: (-item[0], item[1]))
            suffix = [column for _, column in ranked]

            # Replace the purely ranked suffix with the bounded local-exact
            # adjacent-swap refinement required by the strategy.
            suffix = self._refine_leaf(cells, rows, suffix)
            full_order = [lead] + suffix

            for row in rows:
                result[row] = full_order[:]

        return result

    def _candidate(self, cells, orders):
        """Materialize one candidate, score it exactly, and sort rows by serialized text."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global candidates and one swap-refined conditional candidate."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        # Arbitrary swaps cannot safely represent externally supplied merge
        # or dependency constraints, so preserve the source order in those
        # calls while retaining the normal unrestricted optimization path.
        if col_merge or one_way_dep:
            identity = list(range(m))
            candidates = [[identity[:] for _ in range(n)]]
        else:
            global_a = self._global_order(cells, 0)
            global_b = self._global_order(cells, 1)
            conditional = self._conditional_orders(cells)

            candidates = [
                [global_a[:] for _ in range(n)],
                [global_b[:] for _ in range(n)],
                conditional,
            ]

        best = None

        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(-column for column in orders[0])
            choice = (score, signature)

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, _, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column] for column in source_order
            ]
            column_orders.append([
                df.columns[column] for column in source_order
            ])

        # Keep the incumbent return convention: values are reordered and
        # column names remain in the original dataframe schema positions.
        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

